    if (!fightBox || !isVisible(fightBox)) {
      lastPulledRunKey = "";
      return false;
    }
    const fishLeftEl = fightBox.querySelector(".ben-run-fish.left");
    const fishRightEl = fightBox.querySelector(".ben-run-fish.right");
